begin;
with j as (select * from jsonb_to_recordset($law7d0010$[{"code_id":"APK_RF","article_number":"229","version_date":"2002-07-24","article_text":"Принятая по результатам рассмотрения дела резолютивная часть решения размещается в установленном порядке в информационно-телекоммуникационной сети \"Интернет\" не позднее следующего дня после дня ее принятия. (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\nРешения по делам, возникшим из административных и иных публичных правоотношений и рассматриваемым в порядке упрощенного производства, принимаются арбитражным судом по правилам, предусмотренным статьями 201, 206, 211 и 216 настоящего Кодекса.\n\nЗаявление о составлении мотивированного решения арбитражного суда может быть подано в течение пяти дней со дня размещения решения, принятого в порядке упрощенного производства, в установленном порядке в информационно-телекоммуникационной сети \"Интернет\". В этом случае арбитражным судом решение принимается по правилам, установленным главой 20 настоящего Кодекса, если иное не вытекает из особенностей, установленных настоящей главой. (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\nМотивированное решение арбитражного суда изготавливается в течение пяти дней со дня поступления от лица, участвующего в деле, соответствующего заявления или со дня подачи апелляционной жалобы. (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\nЕсли судья, подписавший резолютивную часть решения, отсутствует в день поступления заявления о составлении мотивированного решения или апелляционной жалобы, вопрос о составлении мотивированного решения указанным судьей разрешается в пятидневный срок, начинающий исчисляться с момента возобновления исполнения указанным судьей своих обязанностей. (Дополнение абзацем - Федеральный закон от 25.12.2023 № 667-ФЗ)\n\nВ случае составления мотивированного решения арбитражного суда такое решение вступает в законную силу по истечении срока, установленного для подачи апелляционной жалобы.\n\nВ случае подачи апелляционной жалобы решение арбитражного суда первой инстанции, если оно не отменено или не изменено, вступает в законную силу со дня принятия постановления арбитражным судом апелляционной инстанции.\n\nЭто решение, если оно было предметом рассмотрения в арбитражном суде апелляционной инстанции или если арбитражный суд апелляционной инстанции отказал в восстановлении пропущенного срока подачи апелляционной жалобы, и постановление арбитражного суда апелляционной\n\nинстанции, принятое по данному делу, могут быть обжалованы в арбитражный суд кассационной инстанции по основаниям, предусмотренным частью 3 статьи 2882 настоящего Кодекса. (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n(Статья в редакции Федерального закона от 02.03.2016 № 47-ФЗ)\n\n(Дополнение главой - Федеральный закон от 02.03.2016 № 47-ФЗ)","article_title":"Статья 229. Решение по делу, рассматриваемому в порядке упрощенного производства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fa6dd8bb06ae8e598b4489a0fcbd8ca10eadbc9c9f0ee673679481ed20f4483b"},{"code_id":"APK_RF","article_number":"229.1","version_date":"2002-07-24","article_text":"1. Судебный приказ - судебный акт, вынесенный судьей единолично на основании заявления о взыскании денежных сумм по требованиям взыскателя, предусмотренным статьей 2292 настоящего Кодекса.\n\n2. Судебный приказ является одновременно исполнительным документом и приводится в исполнение в порядке, установленном для исполнения судебных решений.","article_title":"Статья 229.1. Судебный приказ","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e4016b378c79ad60c66f4b680744f97be30a91d63bfe756969207d06a8edabaa"},{"code_id":"APK_RF","article_number":"229.2","version_date":"2002-07-24","article_text":"Судебный приказ выдается по делам, в которых:\n\n1) требования вытекают из неисполнения или ненадлежащего исполнения договора и основаны на представленных взыскателем документах, устанавливающих денежные обязательства, если цена заявленных требований не превышает семьсот пятьдесят тысяч рублей; (В редакции  федеральных законов от 28.11.2018 № 451-ФЗ, от 25.12.2023 № 667-ФЗ)\n\n2) требование основано на совершенном нотариусом протесте векселя в неплатеже, неакцепте и недатировании акцепта, если цена заявленного требования не превышает семьсот пятьдесят тысяч рублей; (В редакции  федеральных законов от 28.11.2018 № 451-ФЗ, от 25.12.2023 № 667-ФЗ)\n\n3) заявлено требование о взыскании обязательных платежей и санкций, если указанный в заявлении общий размер подлежащей взысканию денежной суммы не превышает сто тысяч рублей.","article_title":"Статья 229.2. Дела приказного производства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"19a18cd8982c3bbbe4068a7c81ca8419b0bc7893d8cc945a8d8bd1e7110382a1"},{"code_id":"APK_RF","article_number":"229.3","version_date":"2002-07-24","article_text":"1) наименование арбитражного суда, в который подается заявление;\n\n2) сведения о взыскателе: для взыскателя-гражданина - фамилия, имя, отчество (при наличии), дата и место рождения, место жительства или место пребывания, один из идентификаторов (страховой номер индивидуального лицевого счета, идентификационный номер налогоплательщика, серия и номер документа, удостоверяющего личность, серия и номер водительского удостоверения), для взыскателя-организации - наименование, адрес, идентификационный номер налогоплательщика, реквизиты банковского или казначейского счета и другие необходимые реквизиты; (В редакции Федерального закона от 21.12.2021 № 417-ФЗ)\n\n3) сведения о должнике: для гражданина-должника - фамилия, имя, отчество (при наличии), дата и место рождения, место жительства или место пребывания, место работы (если известно), один из идентификаторов (страховой номер индивидуального лицевого счета, идентификационный номер налогоплательщика, серия и номер документа, удостоверяющего личность, основной государственный регистрационный номер индивидуального предпринимателя, серия и номер водительского удостоверения); для организации-должника - наименование, адрес, идентификационный номер налогоплательщика и основной государственный регистрационный номер; (В редакции Федерального закона от 21.12.2021 № 417-ФЗ)\n\n4) требования взыскателя, в том числе период, за который образовалась взыскиваемая задолженность по обязательствам, предусматривающим исполнение по частям или в виде периодических платежей, размер денежной суммы, составляющей платеж, и ее расчет, а также обстоятельства, на которых основаны указанные требования; (В редакции  Федерального закона от 25.12.2023 № 667-ФЗ)\n\n5) документы, подтверждающие обоснованность требования взыскателя;\n\n6) перечень прилагаемых документов.","article_title":"Статья 229.3. Форма и содержание заявления о выдаче судебного приказа","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"34fd3a1965b648039047a595966044d8fc0715bc45041e4b1e40c09324163913"},{"code_id":"APK_RF","article_number":"229.4","version_date":"2002-07-24","article_text":"1. Арбитражный суд возвращает заявление о выдаче судебного приказа в случае нарушения требований к форме и содержанию заявления о выдаче судебного приказа, установленных статьей 2293 настоящего Кодекса, а также в случаях, если:\n\n1) дело неподсудно данному арбитражному суду;\n\n2) не представлены документы, подтверждающие обоснованность требования взыскателя;\n\n3) отклонено ходатайство о предоставлении отсрочки, рассрочки уплаты государственной пошлины или об уменьшении ее размера;\n\n4) от взыскателя поступило ходатайство о возвращении заявления о выдаче судебного приказа.\n\n2. Возвращение заявления о выдаче судебного приказа не является препятствием для повторного обращения взыскателя в арбитражный суд с заявлением к тому же должнику, с тем же требованием и по тем же основаниям после устранения допущенного нарушения.\n\n3. Арбитражный суд отказывает в принятии заявления о выдаче судебного приказа по основаниям, предусмотренным статьей 1271 настоящего Кодекса, а также в случаях, если:\n\n1) заявлено требование, не предусмотренное статьей 2292 настоящего Кодекса;\n\n2) место жительства или место нахождения должника находится вне пределов Российской Федерации;\n\n3) из заявления о выдаче судебного приказа и приложенных к нему документов усматривается наличие спора о праве.\n\n4. О возвращении заявления о выдаче судебного приказа или об отказе в его принятии арбитражный суд в течение трех дней со дня поступления этого заявления в суд выносит определение, которое может быть обжаловано.\n\n(Статья в редакции Федерального закона от 19.12.2016 № 435-ФЗ)","article_title":"Статья 229.4. Основания для возвращения заявления о выдаче судебного приказа или отказа в его принятии","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8ce529ea10083e7ac024946d814466ec80d167bdd82fe96af7c2af341c67ad26"},{"code_id":"APK_RF","article_number":"229.5","version_date":"2002-07-24","article_text":"1. Заявление по делам приказного производства подается в арбитражный суд по общим правилам подсудности, установленным настоящим Кодексом.\n\n2. Судебный приказ по делам приказного производства выносится арбитражным судом в течение десяти дней со дня поступления заявления о выдаче судебного приказа в арбитражный суд.\n\nСудебный приказ выносится без вызова взыскателя и должника и без проведения судебного разбирательства.\n\nСуд исследует изложенные в направленном взыскателем заявлении о выдаче судебного приказа и приложенных к нему документах сведения в обоснование позиции данного лица и выносит судебный приказ на основании представленных документов.\n\nКопия судебного приказа на бумажном носителе в пятидневный срок со дня вынесения судебного приказа высылается должнику, который в течение десяти дней со дня ее получения вправе представить возражения относительно исполнения судебного приказа.\n\nСудебный приказ размещается в установленном порядке в информационно-телекоммуникационной сети \"Интернет\" не позднее следующего дня после дня его вынесения. (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\nВ определении суда об отмене судебного приказа указывается, что заявленное взыскателем требование может быть предъявлено в порядке искового производства либо производства по делам, возникающим из административных и иных публичных правоотношений.\n\nКопии определения суда об отмене судебного приказа направляются взыскателю и должнику в срок, не превышающий пяти дней со дня вынесения указанного определения. Указанное определение размещается в установленном порядке в информационно-телекоммуникационной сети \"Интернет\" не позднее следующего дня после дня его вынесения. (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\nО возвращении документов, содержащих возражения должника, суд выносит определение.\n\nСудебный приказ может быть направлен судом для исполнения в форме электронного документа, подписанного судьей усиленной квалифицированной электронной подписью в порядке, установленном законодательством Российской Федерации.\n\n(Статья в редакции Федерального закона от 23.06.2016 № 220-ФЗ)","article_title":"Статья 229.5. Порядок приказного производства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c373df54377007475b696404da3032e4cd1cf499dd7c6c5cd1c1732c9f23f462"},{"code_id":"APK_RF","article_number":"229.6","version_date":"2002-07-24","article_text":"1. В судебном приказе указываются:\n\n1) номер дела и дата вынесения судебного приказа;\n\n2) наименование арбитражного суда, фамилия и инициалы судьи, вынесшего судебный приказ;\n\n3) сведения о взыскателе: для гражданина-взыскателя - фамилия, имя, отчество (при наличии), дата и место рождения, место жительства или место пребывания, один из идентификаторов (страховой номер индивидуального лицевого счета, идентификационный номер налогоплательщика, серия и номер документа, удостоверяющего личность, серия и номер водительского удостоверения); для организации-взыскателя - наименование, адрес, идентификационный номер налогоплательщика; (В редакции Федерального закона от 21.12.2021 № 417-ФЗ)\n\n4) сведения о должнике, содержащиеся в заявлении о выдаче судебного приказа: для гражданина-должника - фамилия, имя, отчество (при наличии), дата и место рождения, место жительства или место пребывания, место работы (если известно), один из идентификаторов (страховой номер индивидуального лицевого счета, идентификационный номер налогоплательщика, серия и номер документа, удостоверяющего личность, основной государственный регистрационный номер индивидуального предпринимателя, серия и номер водительского удостоверения); для организации-должника - наименование, адрес, идентификационный номер налогоплательщика и основной государственный регистрационный номер; (В редакции Федерального закона от 21.12.2021 № 417-ФЗ)\n\n5) законы и иные нормативные правовые акты, которыми руководствовался суд при удовлетворении требования;\n\n6) размер денежных сумм, подлежащих взысканию;\n\n7) размер неустойки, если ее взыскание предусмотрено федеральным законом или договором, а также размер пеней, если таковые причитаются;\n\n8) сумма государственной пошлины, подлежащая взысканию с должника в пользу взыскателя или в доход соответствующего бюджета;\n\n9) реквизиты банковского счета взыскателя, на который должны быть перечислены средства, подлежащие взысканию, в случае, если обращение взыскания производится на средства бюджетов бюджетной системы Российской Федерации;\n\n10) период, за который образовалась взыскиваемая задолженность по обязательствам, предусматривающим исполнение по частям или в виде периодических платежей.\n\n(Наименование в редакции Федерального закона от 29.12.2015 № 409-ФЗ)\n\n(Параграф в редакции Федерального закона от 29.12.2015 № 409-ФЗ)","article_title":"Статья 229.6. Содержание судебного приказа","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f843304c0e3ff439d6532942cb0372c4aeabb512f09ddf35668822db297e172f"},{"code_id":"APK_RF","article_number":"23","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 08.12.2011 № 422-ФЗ)\n\nОснованием для отвода эксперта является также проведение им ревизии или проверки, материалы которых стали поводом для обращения в арбитражный суд или используются при рассмотрении дела.","article_title":"Статья 23. Отвод помощника судьи, секретаря судебного заседания, эксперта, специалиста, переводчика","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5727f6a98ef2e99af7a4fb425e906446cc7d5b0fd7087b47761de28d34836102"},{"code_id":"APK_RF","article_number":"230","version_date":"2002-07-24","article_text":"1. Правила, установленные настоящим параграфом, применяются при рассмотрении арбитражным судом заявлений об оспаривании решений третейских судов и международных коммерческих арбитражей (третейских судов) с местом арбитража на территории Российской Федерации.\n\n2. Оспаривание в арбитражном суде решений третейских судов по спорам, возникающим из гражданских правоотношений при осуществлении предпринимательской и иной экономической деятельности, может быть осуществлено лицами, участвующими в третейском разбирательстве, а также иными лицами, в отношении прав и обязанностей которых вынесено решение третейского суда, путем подачи заявления в арбитражный суд об отмене решения третейского суда в соответствии со статьей 233 настоящего Кодекса.\n\n3. С заявлением об отмене решения третейского суда вправе обратиться прокурор по делам, предусмотренным абзацами третьим и четвертым части 1 статьи 52 настоящего Кодекса, если решение третейского суда затрагивает интересы Российской Федерации, субъекта Российской Федерации, муниципального образования, не участвовавших в третейском разбирательстве.\n\n4. Заявление об отмене решения третейского суда подается в арбитражный суд субъекта Российской Федерации, на территории которого принято решение третейского суда, в срок, не превышающий трех месяцев со дня получения оспариваемого решения стороной третейского разбирательства, обратившейся с заявлением, если иное не установлено международным договором Российской Федерации или федеральным законом. По соглашению сторон третейского разбирательства заявление об отмене решения третейского суда может быть подано в арбитражный суд субъекта Российской Федерации по месту нахождения одной из указанных сторон.\n\n5. Лицо, которое не является стороной третейского разбирательства и в отношении прав и обязанностей которого вынесено решение третейского суда, а также прокурор в случаях, установленных настоящей статьей, вправе подать заявление об отмене такого решения в арбитражный суд субъекта Российской Федерации, на территории которого принято решение третейского суда, в срок, не превышающий трех месяцев со дня, когда указанное лицо узнало или должно было узнать об оспариваемом им решении третейского суда.\n\n6. Заявление об отмене решения третейского суда оплачивается государственной пошлиной в размере, предусмотренном федеральным законом для оплаты заявления о выдаче исполнительного листа на принудительное исполнение решения третейского суда.","article_title":"Статья 230. Оспаривание решений третейских судов","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"91bb80a9259832aff79d77c98046276e9cafb674f93e82a5b04bda4f27e6053e"},{"code_id":"APK_RF","article_number":"231","version_date":"2002-07-24","article_text":"1) наименование арбитражного суда, в который подается заявление;\n\n2) состав третейского суда, принявшего решение, его место нахождения, наименование постоянно действующего арбитражного учреждения, администрировавшего соответствующее третейское разбирательство, его место нахождения (в случае наличия постоянно действующего арбитражного учреждения);\n\n3) наименования сторон третейского разбирательства, их адрес или место жительства; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n4) дата и место принятия решения третейского суда;\n\n5) дата получения оспариваемого решения третейского суда стороной, обратившейся с заявлением об отмене указанного решения, либо дата, когда лицо, которое не является стороной третейского разбирательства и в отношении прав и обязанностей которого вынесено решение третейского суда, узнало об оспариваемом им решении;\n\n6) требование заявителя об отмене решения третейского суда, а также основания, по которым оспаривается указанное решение.\n\n1) копия решения третейского суда, подписанного арбитрами и направленного стороне третейского разбирательства в соответствии с федеральным законом;\n\n2) подлинное соглашение о третейском разбирательстве или его надлежащим образом заверенная копия;\n\n3) документы, представляемые в обоснование требования об отмене решения третейского суда;\n\n4) документ, подтверждающий уплату государственной пошлины в порядке и в размере, которые установлены федеральным законом;\n\n5) уведомление о вручении или иной документ, подтверждающий направление копии заявления об отмене решения третейского суда другой стороне третейского разбирательства;\n\n6) доверенность или иной документ, подтверждающие полномочия лица на подписание заявления.","article_title":"Статья 231. Требования к заявлению об отмене решения третейского суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"84d48a7d25d684d76b685a99ade28164d4cde93897fc0a189a3fddcd0f43aff8"},{"code_id":"APK_RF","article_number":"232","version_date":"2002-07-24","article_text":"1. Заявление об отмене решения третейского суда рассматривается судьей единолично по правилам рассмотрения дела арбитражным судом первой инстанции, предусмотренным настоящим Кодексом, с учетом особенностей, установленных настоящим параграфом, в срок, не превышающий одного месяца со дня его поступления в ар\n\nбитражный суд субъекта Российской Федерации.\n\n2. При подготовке дела об отмене решения третейского суда к судебному разбирательству по ходатайству лиц, участвующих в деле, арбитражный суд может истребовать материалы дела, решение по которому оспаривается в арбитражном суде, из постоянно действующего арбитражного учреждения, в котором находятся на хранении материалы третейского дела, или из органа, уполномоченного на хранение материалов третейского дела в соответствии с законодательством Российской Федерации, по правилам, предусмотренным настоящим Кодексом для истребования доказательств.\n\n3. При рассмотрении заявления об отмене решения третейского суда, поданного лицом, которое не является стороной третейского разбирательства и в отношении прав и обязанностей которого вынесено решение третейского суда, арбитражный суд обязан привлечь к участию в деле все стороны третейского разбирательства.\n\n4. Лица, участвующие в деле об отмене решения третейского суда, извещаются арбитражным судом о времени и месте судебного заседания. Неявка указанных лиц, извещенных надлежащим образом о времени и месте проведения судебного заседания, не является препятствием для рассмотрения дела.\n\n5. Если заявление об отмене решения третейского суда подано по основаниям, связанным с тем, что сторона третейского разбирательства не была должным образом уведомлена о назначении третейского судьи или о третейском разбирательстве, в том числе о времени и месте заседания третейского суда, или по другим уважительным причинам не могла представить свои объяснения, либо что решение третейского суда вынесено по спору, не предусмотренному третейским соглашением или не подпадающему под его условия, или содержит постановления по вопросам, выходящим за пределы третейского соглашения, либо что состав третейского суда или арбитражная процедура не соответствовали соглашению сторон или федеральному закону, арбитражный суд по ходатайству стороны третейского разбирательства вправе приостановить производство по делу об отмене решения третейского суда на срок, не превышающий трех месяцев, с тем чтобы третейский суд возобновил третейское разбирательство и устранил основания для отмены арбитражного решения. После возобновления производства по делу об отмене решения третейского суда арбитражный суд рассматривает заявление об отмене решения третейского суда с учетом действий, предпринятых третейским судом в целях устранения оснований для отмены арбитражного решения.\n\n6. При рассмотрении дела арбитражный суд в судебном заседании устанавливает наличие или отсутствие оснований для отмены решения третейского суда, предусмотренных статьей 233 настоящего Кодекса, путем исследования представленных в суд доказательств в обоснование заявленных требований и возражений, но не вправе переоценивать обстоятельства, установленные третейским судом, либо пересматривать решение третейского суда по существу.","article_title":"Статья 232. Порядок рассмотрения заявления об отмене решения третейского суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9d38d845307fc4d641bec8c84d1b4d8f5e6afd8b81ef6d072d46e108f524ae19"},{"code_id":"APK_RF","article_number":"233","version_date":"2002-07-24","article_text":"1. Решение третейского суда может быть отменено арбитражным судом только в случаях, предусмотренных настоящей статьей.\n\n2. Решение третейского суда может быть отменено арбитражным судом по основаниям, установленным частями 3 и 4 настоящей статьи. Решение третейского суда может быть отменено по основаниям, установленным частью 4 настоящей статьи, даже в том случае, если сторона, подавшая заявление об отмене такого решения, не ссылается на указанные основания.\n\n3. Решение третейского суда может быть отменено арбитражным судом лишь в случае, если сторона, подающая заявление об отмене такого решения, представит доказательства того, что:\n\n1) одна из сторон третейского соглашения, на основании которого спор был разрешен третейским судом, не обладала полной дееспособностью;\n\n2) третейское соглашение, на основании которого спор был разрешен третейским судом, недействительно по праву, которому стороны его подчинили, а при отсутствии такого указания - по праву Российской Федерации;\n\n3) решение третейского суда вынесено по спору, не предусмотренному третейским соглашением или не подпадающему под его условия, или содержит постановления по вопросам, выходящим за пределы третейского соглашения. Если постановления третейского суда по вопросам, которые охватываются третейским соглашением, могут быть отделены от постановлений по вопросам, которые не охватываются таким соглашением, может быть отменена только та часть решения, которая содержит постановления по вопросам, не охватываемым третейским соглашением;\n\n4) состав третейского суда или процедура арбитража не соответствовали соглашению сторон или федеральному закону;\n\n5) сторона, против которой принято решение третейского суда, не была должным образом уведомлена об избрании (назначении) третейских судей или о времени и месте заседания третейского суда либо по другим уважительным причинам не могла представить в третейский суд свои объяснения.\n\n4. Арбитражный суд отменяет решение третейского суда, если установит, что:\n\n1) спор, рассмотренный третейским судом, в соответствии с федеральным законом не может быть предметом третейского разбирательства;\n\n2) решение третейского суда противоречит публичному порядку Российской Федерации. Если часть решения третейского суда, которая противоречит публичному порядку Российской Федерации, может быть отделена от той части, которая ему не противоречит, может быть отменена только та часть решения третейского суда, которая противоречит публичному порядку Российской Федерации.\n\n5. Решение международного коммерческого арбитража может быть отменено арбитражным судом по основаниям, предусмотренным международным договором Российской Федерации и федеральным законом о международном коммерческом арбитраже.","article_title":"Статья 233. Основания для отмены решения третейского суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"63b8331c9ad38813b4542def466cfd0a302e7709f3033e9c800dd21f43a8052f"},{"code_id":"APK_RF","article_number":"234","version_date":"2002-07-24","article_text":"1. По результатам рассмотрения заявления об отмене решения третейского суда арбитражный суд выносит определение по правилам, установленным главой 20 настоящего Кодекса для принятия решения.\n\n2. В определении арбитражного суда по делу об оспаривании решения третейского суда должны содержаться:\n\n1) сведения об оспариваемом решении третейского суда и о месте его принятия;\n\n2) сведения о составе третейского суда, принявшего оспариваемое решение;\n\n3) наименования сторон третейского разбирательства;\n\n4) указание на отмену решения третейского суда полностью или в части либо отказ в удовлетворении требования заявителя полностью или в части;\n\n5) в случае отказа в удовлетворении требования заявителя об отмене решения третейского суда полностью или в части указание на возможность получения лицом, в пользу которого вынесено такое решение, исполнительного листа на принудительное исполнение решения третейского суда в порядке, предусмотренном статьей 319 настоящего Кодекса (за исключением случая, предусмотренного пунктом 3 части 7 статьи 238 настоящего Кодекса, если иным арбитражным судом Российской Федерации вынесено определение о выдаче исполнительного листа на принудительное исполнение того же решения третейского суда).\n\n3. Отмена решения третейского суда не препятствует сторонам третейского разбирательства повторно обратиться в третейский суд, если возможность обращения в третейский суд не утрачена, или в арбитражный суд по общим правилам, предусмотренным настоящим Кодексом.\n\n4. В случае, если решение третейского суда отменено арбитражным судом полностью или в части вследствие недействительности третейского соглашения, либо оно было принято по спору, не предусмотренному третейским соглашением или не подпадающему под его условия, либо содержит постановления по вопросам, не охватываемым третейским соглашением, а также если решение третейского суда отменено арбитражным судом в связи с тем, что спор, рассмотренный третейским судом, не может быть предметом третейского разбирательства в соответствии с федеральным законом или решение третейского суда нарушает публичный порядок Российской Федерации, стороны третейского разбирательства могут обратиться за разрешением такого спора в арбитражный суд по общим правилам, предусмотренным настоящим Кодексом.\n\n5. Определение арбитражного суда по делу об оспаривании решения третейского суда может быть обжаловано в кассационном порядке в арбитражный суд округа в течение одного месяца со дня вынесения определения.","article_title":"Статья 234. Определение арбитражного суда по делу об оспаривании решения третейского суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c5f2439d2dcf6863e6566049a731114595695d1c387f136cf853d579428b726d"}]$law7d0010$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
